int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *dev = interface_to_usbdev(intf);
    int err;

    if (dev == NULL)
        return -ENODEV;

    /* Apply any boot quirks */
    err = snd_usb_apply_boot_quirks(dev, intf, usb_id);
    if (err < 0)
        return err;

    /* Check if the device is already registered */
    if (snd_usb_find_card(dev) != NULL)
        return -EBUSY;

    /* Find an available slot and create a new card instance */
    err = snd_card_new(&intf->dev, index, id, THIS_MODULE, 0, NULL);
    if (err < 0)
        return err;

    /* Handle special cases for devices with multiple control interfaces */
    err = snd_usb_handle_multiple_interfaces(dev, intf);
    if (err < 0)
        return err;

    /* Register the card with ALSA */
    err = snd_card_register(NULL);
    if (err < 0) {
        snd_card_free(NULL);
        return err;
    }

    return 0;
}

int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *dev = interface_to_usbdev(intf);
    int err = 0;
    int slot = -1;
    struct snd_card *card = NULL;

    if (snd_usb_check_quirks(dev, usb_id))
        return -ENODEV;

    err = snd_usb_apply_boot_quirk(dev, intf, usb_id, NULL);
    if (err < 0)
        return err;

    if (dev->state != USB_STATE_CONFIGURED)
        return -ENODEV;

    if (snd_device_new(&dev->dev, SNDRV_DEV_LOWLEVEL, NULL, &ops, &card) < 0)
        return -ENOMEM;

    for (int i = 0; i < MAX_CARD_DEVICES; i++) {
        if (!card_devices[i].used) {
            slot = i;
            break;
        }
    }

    if (slot < 0)
        return -ENOSPC;

    card_devices[slot].used = 1;
    card_devices[slot].dev = dev;
    card_devices[slot].intf = intf;

    err = snd_card_register(card, NULL);
    if (err < 0) {
        card_devices[slot].used = 0;
        return err;
    }

    return 0;
}

int snd_usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id) {
    struct usb_device *dev = interface_to_usbdev(intf);
    int err;

    if (dev->quirks & USB_QUIRK_IGNORE) {
        return -ENODEV;
    }

    err = snd_usb_apply_boot_quirk(dev, intf, usb_id, NULL);
    if (err < 0) {
        return err;
    }

    if (dev->is_registered) {
        return -EBUSY;
    }

    struct snd_card *card;
    err = snd_card_new(&dev->dev, index, "USB Audio", THIS_MODULE, 0, &card);
    if (err < 0) {
        return err;
    }

    if (dev->num_interfaces > 1) {
        err = snd_usb_handle_multi_interfaces(dev, intf, card);
        if (err < 0) {
            snd_card_free(card);
            return err;
        }
    }

    err = snd_card_register(card);
    if (err < 0) {
        snd_card_free(card);
        return err;
    }

    dev->card = card;
    dev->is_registered = 1;

    return 0;
}

int usb_audio_probe(struct usb_interface *intf, const struct usb_device_id *usb_id) {
    struct usb_device *dev = interface_to_usbdev(intf);
    int err = -ENODEV;
    int card_index = -1;
    struct snd_card *card = NULL;

    if (!dev)
        return -EINVAL;

    if (dev->quirks & USB_QUIRK_AUDIO) {
        // Apply quirks and handle special cases
        if (usb_apply_boot_quirks(dev) < 0)
            return -ENODEV;
    }

    if (dev->registered)
        return -EBUSY;

    card = snd_card_new(index, id, THIS_MODULE, 0);
    if (!card)
        return -ENOMEM;

    card_index = snd_card_get_index(card);
    if (card_index < 0) {
        snd_card_free(card);
        return card_index;
    }

    // Handle devices with multiple control interfaces
    if (dev->num_interfaces > 1) {
        err = handle_multiple_control_interfaces(dev, card);
        if (err < 0) {
            snd_card_free(card);
            return err;
        }
    }

    err = snd_card_register(card);
    if (err < 0) {
        snd_card_free(card);
        return err;
    }

    dev->registered = true;
    dev->card = card;

    return 0;
}

int register_usb_audio_device(struct usb_interface *intf, const struct usb_device_id *usb_id)
{
    struct usb_device *udev;
    int err;
    int card_index = -1;

    udev = interface_to_usbdev(intf);
    if (!udev)
        return -ENODEV;

    if (quirk_present(udev)) {
        apply_boot_quirks(udev);
    }

    if (is_registered(udev)) {
        return 0;
    }

    card_index = find_available_card_slot();
    if (card_index < 0) {
        return -ENOSPC;
    }

    if (has_multiple_control_interfaces(udev)) {
        handle_multiple_interfaces(udev);
    }

    err = alsa_register_card(card_index, udev);
    if (err < 0) {
        cleanup_card_resources(card_index);
        return err;
    }

    return 0;
}
